struct linearized_sparse_factor_t {
  Eigen::VectorXd residual;              // b
  Eigen::SparseMatrix<double> jacobian;  // J
  Eigen::SparseMatrix<double> hessian;   // H, JtJ
  Eigen::VectorXd rhs;                   // Jtb

  static constexpr const char* getTypeName() {
    return "linearized_sparse_factor_t";
  }
};

struct linearized_sparse_factorf_t {
  Eigen::VectorXf residual;             // b
  Eigen::SparseMatrix<float> jacobian;  // J
  Eigen::SparseMatrix<float> hessian;   // H, JtJ
  Eigen::VectorXf rhs;                  // Jtb

  static constexpr const char* getTypeName() {
    return "linearized_sparse_factorf_t";
  }
};

template <typename ScalarType>
class Factor {
 public:
  using Scalar = ScalarType;

  using LinearizedDenseFactor = typename LinearizedDenseFactorTypeHelper<Scalar>::Type;
  using LinearizedSparseFactor = typename LinearizedSparseFactorTypeHelper<Scalar>::Type;

  template <typename JacobianMatrixType>
  using JacobianFunc = std::function<void(const Values<Scalar>&,
                                          const std::vector<index_entry_t>&,
                                          VectorX<Scalar>* ,
                                          JacobianMatrixType* )>;

  using DenseJacobianFunc = JacobianFunc<MatrixX<Scalar>>;
  using SparseJacobianFunc = JacobianFunc<Eigen::SparseMatrix<Scalar>>;

  template <typename MatrixType>
  using HessianFunc = std::function<void(const Values<Scalar>&,
                                         const std::vector<index_entry_t>&,
                                         VectorX<Scalar>* ,
                                         MatrixType* ,
                                         MatrixType* ,
                                         VectorX<Scalar>* )>;

  using DenseHessianFunc = HessianFunc<MatrixX<Scalar>>;
  using SparseHessianFunc = HessianFunc<Eigen::SparseMatrix<Scalar>>;

  Factor() = default;
  Factor(DenseHessianFunc hessian_func, const std::vector<Key>& keys_to_func,
         const std::vector<Key>& keys_to_optimize = {});
  Factor(SparseHessianFunc hessian_func, const std::vector<Key>& keys_to_func,
         const std::vector<Key>& keys_to_optimize = {});

  Factor(const DenseJacobianFunc& jacobian_func, const std::vector<Key>& keys_to_func,
         const std::vector<Key>& keys_to_optimize = {});
  Factor(const SparseJacobianFunc& jacobian_func, const std::vector<Key>& keys_to_func,
         const std::vector<Key>& keys_to_optimize = {});

  template <typename Functor>
  static Factor Jacobian(Functor&& func, const std::vector<Key>& keys_to_func,
                         const std::vector<Key>& keys_to_optimize = {});

  template <typename Functor>
  static Factor Hessian(Functor&& func, const std::vector<Key>& keys_to_func,
                        const std::vector<Key>& keys_to_optimize = {});

  void Linearize(const Values<Scalar>& values, VectorX<Scalar>* residual,
                 const std::vector<index_entry_t>* maybe_index_entry_cache = nullptr) const;
  void Linearize(const Values<Scalar>& values, VectorX<Scalar>* residual, MatrixX<Scalar>* jacobian,
                 const std::vector<index_entry_t>* maybe_index_entry_cache = nullptr) const;
  void Linearize(const Values<Scalar>& values, VectorX<Scalar>* residual,
                 Eigen::SparseMatrix<Scalar>* jacobian,
                 const std::vector<index_entry_t>* maybe_index_entry_cache = nullptr) const;
  void Linearize(const Values<Scalar>& values, LinearizedDenseFactor& linearized_factor,
                 const std::vector<index_entry_t>* maybe_index_entry_cache = nullptr) const;
  LinearizedDenseFactor Linearize(
      const Values<Scalar>& values,
      const std::vector<index_entry_t>* maybe_index_entry_cache = nullptr) const;
  void Linearize(const Values<Scalar>& values, LinearizedSparseFactor& linearized_factor,
                 const std::vector<index_entry_t>* maybe_index_entry_cache = nullptr) const;

  bool IsSparse() const {
    return static_cast<bool>(sparse_hessian_func_);
  }

  const std::vector<Key>& OptimizedKeys() const;
  const std::vector<Key>& AllKeys() const;

 private:
  DenseHessianFunc hessian_func_;
  SparseHessianFunc sparse_hessian_func_;
  std::vector<Key> keys_to_optimize_;
  std::vector<Key> keys_;
};

using Factord = Factor<double>;
using Factorf = Factor<float>;

template <typename ScalarType, typename _NonlinearSolverType = LevenbergMarquardtSolver<ScalarType>>
class Optimizer {
 public:
  using Scalar = ScalarType;
  using NonlinearSolverType = _NonlinearSolverType;
  using FailureReason = typename NonlinearSolverType::FailureReason;
  using MatrixType = typename NonlinearSolverType::MatrixType;
  using Stats = OptimizationStats<MatrixType>;
  using LinearizerType = internal::LinearizerSelector_t<MatrixType>;

  Optimizer(const optimizer_params_t& params, std::vector<Factor<Scalar>> factors,
            const std::string& name = "sym::Optimize", std::vector<Key> keys = {},
            const Scalar epsilon = sym::kDefaultEpsilon<Scalar>);

  template <typename... NonlinearSolverArgs>
  Optimizer(const optimizer_params_t& params, std::vector<Factor<Scalar>> factors,
            const std::string& name, std::vector<Key> keys, Scalar epsilon,
            NonlinearSolverArgs&&... nonlinear_solver_args);

  Optimizer(Optimizer&&) = delete;
  Optimizer& operator=(Optimizer&&) = delete;
  Optimizer(const Optimizer&) = delete;
  Optimizer& operator=(const Optimizer&) = delete;

  virtual ~Optimizer() = default;

  Stats Optimize(Values<Scalar>& values, int num_iterations = -1,
                 bool populate_best_linearization = false);
  virtual void Optimize(Values<Scalar>& values, int num_iterations,
                        bool populate_best_linearization, Stats& stats);
  void Optimize(Values<Scalar>& values, int num_iterations, Stats& stats);
  void Optimize(Values<Scalar>& values, Stats& stats);

  Linearization<MatrixType> Linearize(const Values<Scalar>& values);

  void ComputeAllCovariances(const Linearization<MatrixType>& linearization,
                             std::unordered_map<Key, MatrixX<Scalar>>& covariances_by_key);

  Eigen::ComputationInfo ComputeCovariances(
      const Linearization<MatrixType>& linearization, const std::vector<Key>& keys,
      std::unordered_map<Key, MatrixX<Scalar>>& covariances_by_key,
      bool c_is_block_diagonal = true);

  void ComputeFullCovariance(const Linearization<MatrixType>& linearization,
                             MatrixX<Scalar>& covariance);

  const std::vector<Key>& Keys() const;
  const std::vector<Factor<Scalar>>& Factors() const;
  const LinearizerType& Linearizer() const;
  LinearizerType& Linearizer();
  const NonlinearSolverType& NonlinearSolver() const;
  NonlinearSolverType& NonlinearSolver();
  void UpdateParams(const optimizer_params_t& params);
  const optimizer_params_t& Params() const;

 protected:
  typename NonlinearSolverType::LinearizeFunc BuildLinearizeFunc(bool check_derivatives);
  bool IsInitialized() const;
  void Initialize(const Values<Scalar>& values);
  void MaybeLogStatus(const Stats& stats) const;
  const std::string& GetName();

  std::vector<Factor<Scalar>> factors_;
  std::string name_;
  NonlinearSolverType nonlinear_solver_;
  Scalar epsilon_;
  bool debug_stats_;
  bool include_jacobians_;
  std::vector<Key> keys_;
  index_t index_;
  LinearizerType linearizer_;

  struct ComputeCovariancesStorage {
    sym::MatrixX<Scalar> covariance;
    MatrixType H_damped;
  };

  mutable ComputeCovariancesStorage compute_covariances_storage_;
  typename NonlinearSolverType::LinearizeFunc linearize_func_;
  bool verbose_;
};

using Optimizerd = Optimizer<double>;
using Optimizerf = Optimizer<float>;

namespace sym {

template <typename ScalarType>
class Rot2 {
 public:
  using Scalar = ScalarType;
  using Self = Rot2<Scalar>;
  using DataVec = Eigen::Matrix<Scalar, 2, 1, Eigen::DontAlign>;
  using TangentVec = Eigen::Matrix<Scalar, 1, 1>;
  using SelfJacobian = Eigen::Matrix<Scalar, 1, 1>;

  explicit Rot2(const DataVec& data, const bool normalize = true)
      : data_(normalize ? DataVec(data.normalized()) : data) {}

  Rot2() : Rot2(GroupOps<Self>::Identity()) {}

  inline const DataVec& Data() const {
    return data_;
  }

  using Vector2 = Eigen::Matrix<Scalar, 2, 1>;

  static Rot2 RandomFromUniformSamples(const Scalar u1) {
    const Scalar theta = 2 * M_PI * u1;
    return Rot2(Eigen::Matrix<Scalar, 2, 1>(std::cos(theta), std::sin(theta)));
  }

  template <typename Generator>
  static Rot2 Random(Generator& gen) {
    std::uniform_real_distribution<Scalar> dist(0.0, 1.0);
    return RandomFromUniformSamples(dist(gen));
  }

  explicit Rot2(const Scalar angle) : Rot2(FromAngle(angle)) {}

  const Vector2 ComposeWithPoint(const Vector2& right) const;
  const Scalar ToAngle(const Scalar epsilon) const;
  const static sym::Rot2<Scalar> FromAngle(const Scalar theta);
  const Eigen::Matrix<Scalar, 2, 2> ToRotationMatrix() const;
  const static sym::Rot2<Scalar> FromRotationMatrix(const Eigen::Matrix<Scalar, 2, 2>& r);
  const static sym::Rot2<Scalar> RandomFromUniformSample(const Scalar u1);

  static constexpr int32_t StorageDim() {
    return StorageOps<Self>::StorageDim();
  }
  void ToStorage(Scalar* const vec) const {
    return StorageOps<Self>::ToStorage(*this, vec);
  }
  static Rot2 FromStorage(const Scalar* const vec) {
    return StorageOps<Self>::FromStorage(vec);
  }
  Vector2 Compose(const Vector2& point) const { return ComposeWithPoint(point); }

  static Self Identity() { return GroupOps<Self>::Identity(); }
  Self Inverse() const { return GroupOps<Self>::Inverse(*this); }
  Self Compose(const Self& b) const { return GroupOps<Self>::Compose(*this, b); }
  Self Between(const Self& b) const { return GroupOps<Self>::Between(*this, b); }
  Self InverseWithJacobian(SelfJacobian* const res_D_a = nullptr) const {
    return GroupOps<Self>::InverseWithJacobian(*this, res_D_a);
  }
  Self ComposeWithJacobians(const Self& b, SelfJacobian* const res_D_a = nullptr,
                            SelfJacobian* const res_D_b = nullptr) const {
    return GroupOps<Self>::ComposeWithJacobians(*this, b, res_D_a, res_D_b);
  }
  Self BetweenWithJacobians(const Self& b, SelfJacobian* const res_D_a = nullptr,
                            SelfJacobian* const res_D_b = nullptr) const {
    return GroupOps<Self>::BetweenWithJacobians(*this, b, res_D_a, res_D_b);
  }

  template <typename Other>
  auto operator*(const Other& b) const -> decltype(Compose(b)) { return Compose(b); }

  static constexpr int32_t TangentDim() { return LieGroupOps<Self>::TangentDim(); }
  static Self FromTangent(const TangentVec& vec, const Scalar epsilon = kDefaultEpsilon<Scalar>) {
    return LieGroupOps<Self>::FromTangent(vec, epsilon);
  }
  TangentVec ToTangent(const Scalar epsilon = kDefaultEpsilon<Scalar>) const {
    return LieGroupOps<Self>::ToTangent(*this, epsilon);
  }
  Self Retract(const TangentVec& vec, const Scalar epsilon = kDefaultEpsilon<Scalar>) const {
    return LieGroupOps<Self>::Retract(*this, vec, epsilon);
  }
  TangentVec LocalCoordinates(const Self& b, const Scalar epsilon = kDefaultEpsilon<Scalar>) const {
    return LieGroupOps<Self>::LocalCoordinates(*this, b, epsilon);
  }
  Self Interpolate(const Self b, const Scalar alpha,
                   const Scalar epsilon = kDefaultEpsilon<Scalar>) const {
    return LieGroupOps<Self>::Interpolate(*this, b, alpha, epsilon);
  }

  bool IsApprox(const Self& b, const Scalar tol) const {
    if (b.Data() == DataVec::Zero()) {
      return Data().norm() < tol;
    }
    return Data().isApprox(b.Data(), tol);
  }

  template <typename ToScalar>
  Rot2<ToScalar> Cast() const {
    return Rot2<ToScalar>(Data().template cast<ToScalar>());
  }

  bool operator==(const Rot2& rhs) const { return data_ == rhs.Data(); }
  bool operator!=(const Rot2& rhs) const { return !(*this == rhs); }

 protected:
  DataVec data_;
};

using Rot2d = Rot2<double>;
using Rot2f = Rot2<float>;

