  using Vector2 = Eigen::Matrix<Scalar, 2, 1>;

  template <typename Derived>
  Pose2(const Rot2<Scalar>& rotation, const Eigen::MatrixBase<Derived>& position) {
    static_assert(Derived::RowsAtCompileTime == 2, "Position must be a 2x1 vector");
    static_assert(Derived::ColsAtCompileTime == 1, "Position must be a 2x1 vector");
    data_.template head<2>() = rotation.Data();
    data_.template tail<2>() = position;
  }

  template <typename Generator>
  static Pose2 Random(Generator& gen) {
    return Pose2(Rot2<Scalar>::Random(gen), sym::StorageOps<Vector2>::Random(gen));
  }

  Eigen::Transform<Scalar, 2, Eigen::TransformTraits::Isometry> ToTransform() const {
    return Eigen::Transform<Scalar, 2, Eigen::TransformTraits::Isometry>{ToHomogenousMatrix()};
  }

  sym::Rot2<Scalar> Rotation() const { return sym::Rot2<Scalar>(RotationStorage(), /* normalize */ false); }

  const Vector2 RotationStorage() const;
  const Vector2 Position() const;
  const Vector2 ComposeWithPoint(const Vector2& right) const;
  const Vector2 InverseCompose(const Vector2& point) const;
  const Eigen::Matrix<Scalar, 3, 3> ToHomogenousMatrix() const;

  static constexpr int32_t StorageDim() { return StorageOps<Self>::StorageDim(); }
  void ToStorage(Scalar* const vec) const { return StorageOps<Self>::ToStorage(*this, vec); }
  static Pose2 FromStorage(const Scalar* const vec) { return StorageOps<Self>::FromStorage(vec); }
  Vector2 Compose(const Vector2& point) const { return ComposeWithPoint(point); }

  static Self Identity() { return GroupOps<Self>::Identity(); }
  Self Inverse() const { return GroupOps<Self>::Inverse(*this); }
  Self Compose(const Self& b) const { return GroupOps<Self>::Compose(*this, b); }
  Self Between(const Self& b) const { return GroupOps<Self>::Between(*this, b); }
  Self InverseWithJacobian(SelfJacobian* const res_D_a = nullptr) const { return GroupOps<Self>::InverseWithJacobian(*this, res_D_a); }
  Self ComposeWithJacobians(const Self& b, SelfJacobian* const res_D_a = nullptr,
