    (0x1F300, 0x1F64F), # Misc symbols and pictographs (emoji)
]

PRINTABLE_ASCII = string.ascii_letters + string.digits + string.punctuation + " "


def _rand_unicode_char(rng: random.Random) -> str:
    # Pick a range, then a code point, skipping surrogates
    start, end = rng.choice(UNICODE_RANGES)
    cp = rng.randint(start, end)
    # Skip surrogate range
    if 0xD800 <= cp <= 0xDFFF:
        cp = 0xE000 + (cp - 0xD800)  # map out of surrogate area
    try:
        return chr(cp)
    except ValueError:
        return "?"


def _rand_ascii_token(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(PRINTABLE_ASCII) for _ in range(n))


def _rand_unicode_token(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(_rand_unicode_char(rng) for _ in range(n))


def _mix_segments(rng: random.Random) -> str:
    segments: List[str] = []
    # Start with a curated substring sometimes
    if rng.random() < 0.7:
        segments.append(rng.choice(INTERESTING_SUBSTRS))
    # Add several random segments of varying types
    for _ in range(rng.randint(2, 6)):
        kind = rng.random()
        if kind < 0.4:
            segments.append(_rand_ascii_token(rng, 1, 32))
        elif kind < 0.8:
            segments.append(_rand_unicode_token(rng, 1, 16))
        else:
            segments.append(rng.choice(INTERESTING_SUBSTRS))
    # Occasionally include long sequences near limits
    if rng.random() < 0.25:
        long_choice = rng.choice([
            "x" * rng.randint(128, 512),
            _rand_unicode_token(rng, 64, 256),
        ])
        segments.append(long_choice)
    # Occasionally include line breaks and tabs
    if rng.random() < 0.5:
        segments.append("\n")
    if rng.random() < 0.3:
        segments.append("\t")
    return ''.join(segments)


def _truncate_to_max_bytes(s: str, max_bytes: int) -> str:
    b = s.encode('utf-8', errors='ignore')
    if len(b) <= max_bytes:
        return s
    # Truncate safely on byte boundary: find a cut that decodes
    cut = max_bytes
    # Step backward up to 4 bytes to avoid splitting a multibyte sequence
    for back in range(0, 4):
        try_cut = max_bytes - back
        if try_cut < 0:
            break
        try:
            return b[:try_cut].decode('utf-8', errors='strict')
        except UnicodeDecodeError:
            continue
    # As a fallback, decode with ignore
    return b[:max_bytes].decode('utf-8', errors='ignore')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide overall strategy
    strategy = rng.random()
    if strategy < 0.15:
        # Pure ASCII printable, variable length
        target_len = rng.randint(0, 1024)
        s = _rand_ascii_token(rng, target_len, target_len)
    elif strategy < 0.30:
        # Single curated interesting substring
        s = rng.choice(INTERESTING_SUBSTRS)
    elif strategy < 0.85:
        # Mixed segments
        s = _mix_segments(rng)
    else:
        # High-unicode heavy
        pieces = [_rand_unicode_token(rng, 1, 32) for _ in range(rng.randint(3, 10))]
        s = ''.join(pieces)

    # Randomly wrap with quotes, brackets, or add prefix/suffix markers
    wrappers = [
        ("", ""),
        ("[", "]"), ("{", "}"), ("(", ")"),
        ("\"", "\""), ("'", "'"),
        ("<", ">"), ("`", "`"),
    ]
    if rng.random() < 0.4:
        left, right = rng.choice(wrappers)
        s = left + s + right
    if rng.random() < 0.4:
        s = f"name:{s}"
    if rng.random() < 0.2:
        s = s + "::" + _rand_ascii_token(rng, 1, 16)

    # Ensure total size <= MAX_BYTES
    s = _truncate_to_max_bytes(s, MAX_BYTES)

    return s.encode('utf-8')
